def e(x): return escape(str(x or ''),quote=True)
def icon(name='arrow'):
    paths={'arrow':'<path d="M5 19 19 5M5 5h14v14"/>','next':'<path d="M4 12h16m-6-6 6 6-6 6"/>','play':'<path d="m8 5 11 7-11 7Z" fill="currentColor" stroke="none"/>','menu':'<path d="M4 6h16M4 12h16M4 18h16"/>','close':'<path d="m6 6 12 12M6 18 18 6"/>','book':'<path d="M12 5v15M3 4c4-1 6 0 9 2 3-2 5-3 9-2v14c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>','expand':'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>','youtube':'<rect x="2" y="5" width="20" height="14" rx="4" fill="currentColor" stroke="none"/><path d="m10 9 6 3-6 3Z" fill="white" stroke="none"/>','playlist':'<path d="M3 5h14M3 10h14M3 15h8m5-1 6 4-6 4Z"/>','mail':'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>'}
