    return intro('AI innovations','Ideas you can<br>put your hands on.','Learning companions, classroom experiments, and small tools that make complex ideas easier to explore.')+f'''<section class="section" id="python-ki-pathshala"><div class="wrap"><div class="innovation-feature"><div class="innovation-copy"><div class="overline">Featured learning companion</div><h3>Python Ki Pathshala</h3><p>Learn Python through Hindi, English, or Hinglish. Ask a question, explore a familiar example, and build your understanding one concept at a time.</p>{link(GPT,'Open Python Ki Pathshala')}{link('recognition.html#pathshala','Explore the case study')}</div>{tutor()}</div></div></section><section class="section light" id="labs"><div class="wrap"><div class="section-intro"><div class="overline">The interactive classroom</div><h2>Change a parameter.<br>Discover an idea.</h2><p>These interactive demonstrations are ready to explore. Use them for individual learning, classroom explanation, or a deeper discussion.</p></div><div class="tool-grid">{cards}</div><div class="resource-banner"><div><h3>The complete teaching collection</h3><p>Find activity descriptions, classroom applications, and links to every learning lab.</p></div>{btn('teaching-demonstrations.html','View teaching demonstrations','btn-white')}</div>{follow_note('Found something useful?', 'Follow me on LinkedIn for new learning tools, classroom experiments, and practical AI resources.')}</div></section><section class="section"><div class="wrap"><div class="section-head"><h2>From learning to everyday practice.</h2></div><div class="topics-grid"><article class="topic-card"><h3>AI for Everyone</h3><p>My instructional contribution to the E&ICT Academy, IIT Kanpur programme introduces practical Generative AI and useful AI workflows.</p>{link('https://www.eicta.iitk.ac.in/payment/ai-for-everyone?mode=SELF_PACED','Explore the programme')}</article><article class="topic-card"><h3>Google Drive File Picker</h3><p>A Chrome extension for selecting Google Drive files and attaching them to ChatGPT-compatible workflows. Find installation details, product information, and privacy policies.</p>{link('extension.html','Explore the Chrome extension')}<p><a href="privacy.html"><u>Privacy policy</u></a> · <a href="terms.html"><u>Terms</u></a></p></article></div></div></section>{collab()}'''
